eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   emptyStates: () => (/* binding */ emptyStates)\n/* harmony export */ });\n/** UX Foundations — empty states: the screen isn't \"nothing\", it's a message + a next step. */ const emptyStates = {\n    id: 'empty-states',\n    slug: 'empty-states',\n    title: 'Пустые состояния и онбординг',\n    pathTitle: 'UX Foundations',\n    skill: 'empty-states',\n    difficulty: 'medium',\n    estimatedMinutes: 10,\n    objectives: [\n        'Различать три причины пустого экрана и подбирать под каждую своё сообщение',\n        'Использовать пустое состояние как шанс объяснить ценность и предложить действие',\n        'Понимать, когда контекстная подсказка работает лучше отдельного тура-онбординга'\n    ],\n    prerequisites: [\n        'forms'\n    ],\n    theory: [\n        '**Пустое состояние — отдельный экран**, а не «нечего показывать». Голое «Нет данных» оставляет человека без понимания, что делать дальше.',\n        'Причины пустоты разные, и у каждой — своё сообщение: **ещё не создано** (нужен CTA «создать первое»), **ничего не найдено** по фильтру/поиску (нужен способ сбросить условия), **ошибка загрузки** (нужна кнопка «повторить»). Один и тот же текст на все три случая путает.',\n        'Онбординг работает лучше всего **встроенным в момент, когда он нужен** — короткая подсказка рядом с элементом в первый раз, когда человек до него дошёл, а не тур из 5 экранов до того, как он вообще увидел продукт.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: '«Нет данных» — без объяснения и без действия',\n            visual: 'empty-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Иконка + объяснение ценности + кнопка действия',\n            visual: 'empty-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'es-choose-1',\n            type: 'choose',\n            prompt: 'Пользователь впервые открыл раздел «Проекты» — он ещё ничего не создавал. Что должно быть на экране?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Просто пустой белый экран',\n                    hint: 'Нет ни объяснения, ни следующего шага.'\n                },\n                {\n                    id: 'b',\n                    label: 'Текст «Нет данных» без пояснений',\n                    hint: 'Не объясняет, что делать дальше.'\n                },\n                {\n                    id: 'c',\n                    label: 'Иконка + объяснение ценности раздела + кнопка «Создать первый проект»'\n                },\n                {\n                    id: 'd',\n                    label: 'Мгновенный редирект на форму создания без объяснения',\n                    hint: 'Слишком резко — человек не успел понять, куда попал и зачем.'\n                }\n            ],\n            correctOptionId: 'c',\n            explanation: 'Для сценария «ещё не создано» пустое состояние — это шанс объяснить ценность раздела и сразу предложить самое логичное действие: создать первую запись.'\n        },\n        {\n            id: 'es-choose-2',\n            type: 'choose',\n            prompt: 'Поиск по каталогу ничего не нашёл по запросу пользователя. Какое сообщение уместно?',\n            options: [\n                {\n                    id: 'a',\n                    label: '«Ничего не найдено» + предложение изменить запрос или сбросить фильтры'\n                },\n                {\n                    id: 'b',\n                    label: 'Тот же экран, что и для «данных вообще ещё нет»',\n                    hint: 'Разные причины пустоты требуют разных сообщений и разных действий.'\n                },\n                {\n                    id: 'c',\n                    label: 'Редирект на главную без объяснения',\n                    hint: 'Теряет контекст запроса — человеку придётся искать заново с нуля.'\n                },\n                {\n                    id: 'd',\n                    label: 'Бесконечный спиннер загрузки',\n                    hint: 'Это не пустое состояние, а баг — поиск должен завершиться результатом или его отсутствием.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: '«Ничего не найдено» — не то же самое, что «данных ещё нет»: человек уже знает, что каталог не пуст, ему нужен способ поправить запрос, а не CTA «создать».'\n        },\n        {\n            id: 'es-choose-3',\n            type: 'choose',\n            prompt: 'Когда тур-онбординг (несколько экранов подряд перед началом работы) работает хуже контекстных подсказок?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Когда пользователь ещё не увидел ни одного реального экрана продукта'\n                },\n                {\n                    id: 'b',\n                    label: 'Когда в продукте больше одной функции',\n                    hint: 'Число функций само по себе не определяет, какой формат онбординга лучше.'\n                },\n                {\n                    id: 'c',\n                    label: 'Когда экран содержит форму',\n                    hint: 'Тип экрана не определяет формат онбординга.'\n                },\n                {\n                    id: 'd',\n                    label: 'Когда у продукта тёмная тема',\n                    hint: 'Тема оформления никак не связана с выбором формата онбординга.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Тур из абстрактных слайдов до первого реального экрана плохо запоминается — человеку не на что это спроецировать. Подсказка, показанная у самого элемента в момент, когда он нужен, привязана к контексту и потому лучше усваивается.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'es-figma-1',\n        type: 'figma-link',\n        prompt: 'Спроектируй в Figma три состояния одного и того же списка: обычный список с данными, «данных ещё нет», «ничего не найдено по запросу». Общий layout должен быть узнаваем во всех трёх.',\n        checklist: [\n            'Есть отдельный дизайн для «данных ещё нет» с объяснением и CTA создания',\n            'Есть отдельный дизайн для «ничего не найдено» со способом сбросить/изменить запрос',\n            'Все три состояния явно принадлежат одному и тому же экрану'\n        ],\n        explanation: 'Три разных пустых состояния для одного списка показывают, что дизайнер продумал не только happy path с данными, но и оба типа «пусто» — с разными сообщениями под разные причины.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/empty-states.ts\n");

