eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   formsStructure: () => (/* binding */ formsStructure)\n/* harmony export */ });\n/**\n * UX Foundations — forms series, part 3 of 3.\n * Structure and long forms: grouping, order, chunking into steps, and cutting\n * fields that don't earn their place.\n */ const formsStructure = {\n    id: 'forms-structure',\n    slug: 'forms-structure',\n    title: 'Формы: структура и длинные формы',\n    pathTitle: 'UX Foundations',\n    skill: 'forms',\n    difficulty: 'medium',\n    estimatedMinutes: 10,\n    objectives: [\n        'Группировать поля по смыслу и логичному порядку',\n        'Разбивать длинные формы на шаги с прогрессом',\n        'Убирать поля, которые не оправдывают своё место'\n    ],\n    prerequisites: [\n        'forms'\n    ],\n    theory: [\n        'Финальный урок про формы — про форму как целое: порядок, группировку и длинные анкеты.',\n        '**Группировка по смыслу** снижает нагрузку сильнее, чем просто сокращение числа полей: форма из 8 полей в 3 понятных блоках читается легче формы из 5 вперемешку. Порядок блоков — логичный: кто ты → как связаться → защита доступа → действие.',\n        '**Длинные формы — на шаги.** Многошаговый мастер с индикатором прогресса не пугает, как одна простыня из 30 полей. Человек видит, сколько осталось, и идёт по частям.',\n        '**Каждое поле оправдывает место.** Спрашивай только то, что реально нужно сейчас. Необязательное — убери или отложи. Одно поле в строку обычно читается лучше, чем несколько в ряд.'\n    ],\n    examples: [],\n    exercises: [\n        {\n            id: 'fs-order-1',\n            type: 'order',\n            prompt: 'Собери форму регистрации из смысловых блоков: сверху вниз.',\n            items: [\n                {\n                    id: 'personal',\n                    label: 'Имя и фамилия',\n                    size: 'body'\n                },\n                {\n                    id: 'contact',\n                    label: 'Email и телефон',\n                    size: 'body'\n                },\n                {\n                    id: 'security',\n                    label: 'Пароль',\n                    size: 'body'\n                },\n                {\n                    id: 'submit',\n                    label: 'Кнопка «Зарегистрироваться»',\n                    size: 'button'\n                }\n            ],\n            correctOrder: [\n                'personal',\n                'contact',\n                'security',\n                'submit'\n            ],\n            explanation: 'Сначала блок про то, кто человек (имя), затем как с ним связаться (контакты), затем защита доступа (пароль) — и только в конце действие. Каждый блок — законченная смысловая группа, а не вперемешку.'\n        },\n        {\n            id: 'fs-choose-1',\n            type: 'choose',\n            prompt: 'Анкета на 25 полей на одном экране пугает и её бросают. Что сделать?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Разбить на шаги с индикатором прогресса и убрать лишние поля'\n                },\n                {\n                    id: 'b',\n                    label: 'Оставить всё, но уменьшить шрифт, чтобы поместилось',\n                    hint: 'Мелкий шрифт не убирает объём — только усложняет чтение.'\n                },\n                {\n                    id: 'c',\n                    label: 'Сложить поля в два-три столбца',\n                    hint: 'Многоколоночные формы сбивают порядок чтения и заполнения.'\n                },\n                {\n                    id: 'd',\n                    label: 'Сделать всё обязательным, чтобы точно заполнили',\n                    hint: 'Больше обязательных полей — выше отток, а не ниже.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Длинную форму спасают два приёма: разбить на шаги с прогрессом (видно, сколько осталось) и вырезать поля, без которых можно обойтись сейчас. Объём воспринимается легче, а отток падает.'\n        },\n        {\n            id: 'fs-choose-2',\n            type: 'choose',\n            prompt: 'Что обычно лишнее в форме заказа доставки?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Необязательное поле «Как вы о нас узнали?»'\n                },\n                {\n                    id: 'b',\n                    label: 'Адрес доставки',\n                    hint: 'Без адреса заказ не доставить — это ядро формы.'\n                },\n                {\n                    id: 'c',\n                    label: 'Способ оплаты',\n                    hint: 'Оплата нужна, чтобы завершить заказ.'\n                },\n                {\n                    id: 'd',\n                    label: 'Контакт для связи по заказу',\n                    hint: 'Нужен, чтобы уточнить детали доставки.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Маркетинговый вопрос «как узнали о нас» не нужен для выполнения заказа — его убирают из основного пути или делают необязательным и незаметным. Адрес, оплата и контакт — часть цели, их не тронуть.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'fs-figma-1',\n        type: 'figma-link',\n        prompt: 'Спроектируй в Figma форму регистрации на 5-6 полей: постоянные label (не placeholder), инлайн-ошибка хотя бы для одного поля, явная пометка обязательности, поля сгруппированы по смыслу.',\n        checklist: [\n            'Label остаётся видимым, а не исчезает при вводе',\n            'Хотя бы одна ошибка показана рядом с конкретным полем, не общей фразой',\n            'Обязательные/необязательные поля помечены явно',\n            'Поля сгруппированы по смыслу, а не одним сплошным списком'\n        ],\n        explanation: 'Форма с постоянными label, точечными ошибками и явной группировкой снижает трение регистрации сильнее, чем просто уменьшение числа полей — потому что читается и заполняется быстрее.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/forms-structure.ts\n");

