eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   informationArchitecture: () => (/* binding */ informationArchitecture)\n/* harmony export */ });\n/**\n * UX Foundations — user flows series, part 3 of 3.\n * Information architecture: organising content around the user's mental model\n * so things are findable — grouping, labels, navigation depth.\n */ const informationArchitecture = {\n    id: 'information-architecture',\n    slug: 'information-architecture',\n    title: 'Информационная архитектура',\n    pathTitle: 'UX Foundations',\n    skill: 'flows',\n    difficulty: 'medium',\n    estimatedMinutes: 11,\n    objectives: [\n        'Группировать по ментальной модели пользователя, а не по оргструктуре',\n        'Давать понятные ярлыки на языке пользователя',\n        'Держать навигацию неглубокой и предсказуемой'\n    ],\n    prerequisites: [\n        'user-flows'\n    ],\n    theory: [\n        'Финальный урок серии — про то, как устроен **контент и навигация**, чтобы человек находил нужное, не думая.',\n        '**Группируй по ментальной модели пользователя**, а не по внутренней структуре компании. Пользователю неважно, какой отдел отвечает за раздел — важно, где он ожидает его найти.',\n        '**Ярлыки — на языке пользователя.** «Личный кабинет», а не «Модуль CRM». Непонятный пункт меню люди просто пролистывают.',\n        '**Глубина vs ширина.** Слишком глубоко (7 кликов до цели) — теряются по дороге; слишком широко (40 пунктов в меню) — перегруз. Ищем баланс, где путь короткий и предсказуемый.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Пункты меню на внутреннем жаргоне, вперемешку',\n            visual: 'nav-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Понятные ярлыки, сгруппированные по смыслу',\n            visual: 'nav-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'ia-choose-1',\n            type: 'choose',\n            prompt: 'По какому принципу лучше группировать разделы в навигации?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'По ментальной модели пользователя — где он ожидает найти'\n                },\n                {\n                    id: 'b',\n                    label: 'По внутренней оргструктуре компании',\n                    hint: 'Пользователь не знает и не хочет знать, какой отдел за что отвечает.'\n                },\n                {\n                    id: 'c',\n                    label: 'По алфавиту названий разделов',\n                    hint: 'Алфавит редко совпадает со смыслом и логикой задач.'\n                },\n                {\n                    id: 'd',\n                    label: 'По дате добавления раздела',\n                    hint: 'Хронология создания не помогает искать нужное.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Хорошая ИА повторяет ментальную модель пользователя: разделы там, где их ожидают. Группировка по оргструктуре удобна команде, но заставляет пользователя гадать, куда положили нужное.'\n        },\n        {\n            id: 'ia-match',\n            type: 'match',\n            prompt: 'Переведи пункт меню с внутреннего жаргона на язык пользователя.',\n            pairs: [\n                {\n                    id: 'p1',\n                    left: 'Модуль CRM',\n                    right: 'Клиенты'\n                },\n                {\n                    id: 'p2',\n                    left: 'Биллинг-центр',\n                    right: 'Оплата и счета'\n                },\n                {\n                    id: 'p3',\n                    left: 'Ассет-менеджер',\n                    right: 'Мои файлы'\n                }\n            ],\n            explanation: 'Ярлыки должны говорить словами пользователя. Внутренние названия систем понятны команде, но для человека это шум — он не свяжет «Ассет-менеджер» со своими файлами.'\n        },\n        {\n            id: 'ia-choose-2',\n            type: 'choose',\n            prompt: 'Чтобы редкий, но важный раздел стало легче найти, лучше всего…',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Поднять его в предсказуемое место + дать поиск по разделам'\n                },\n                {\n                    id: 'b',\n                    label: 'Спрятать поглубже — раз он редкий',\n                    hint: 'Редкий не значит неважный; важное не прячут за 6 кликов.'\n                },\n                {\n                    id: 'c',\n                    label: 'Добавить его во все меню сразу',\n                    hint: 'Дублирование повсюду создаёт шум и путаницу.'\n                },\n                {\n                    id: 'd',\n                    label: 'Переименовать в модный термин',\n                    hint: 'Непонятный ярлык только ухудшает нахождение.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Findability — про то, чтобы нужное находилось быстро: понятное место в структуре плюс поиск как запасной путь. Прятать важное «поглубже» из-за редкости — прямой путь к тому, что им перестанут пользоваться.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'ia-choose-mastery',\n        type: 'choose',\n        prompt: 'В приложении банка раздел «Выписка» пользователи ищут в среднем 5 кликов и часто не находят. Что сделать по ИА?',\n        options: [\n            {\n                id: 'a',\n                label: 'Положить «Выписку» внутрь «Счёта/История» — где её и ищут — и добавить в поиск'\n            },\n            {\n                id: 'b',\n                label: 'Оставить как есть, написать инструкцию в справке',\n                hint: 'Справку не читают; проблему структуры справкой не лечат.'\n            },\n            {\n                id: 'c',\n                label: 'Вынести отдельной крупной кнопкой на главный экран для всех',\n                hint: 'Редкую задачу нельзя ставить в центр для всех — это перегрузит главный экран.'\n            },\n            {\n                id: 'd',\n                label: 'Переименовать в «Транзакционный отчёт»',\n                hint: 'Более технический ярлык только ухудшит нахождение.'\n            }\n        ],\n        correctOptionId: 'a',\n        explanation: 'Решение — совпасть с ментальной моделью: выписку ищут рядом со счётом и историей, туда её и кладём, плюс поиск как запасной путь. Это сокращает путь и делает раздел находимым, не перегружая главный экран.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/information-architecture.ts\n");

