eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   insightsToConcept: () => (/* binding */ insightsToConcept)\n/* harmony export */ });\n/**\n * Design Process — series part 3 of 3.\n * From raw research to a direction: synthesis into insights, moodboard/concept,\n * and wireframes before visual polish.\n */ const insightsToConcept = {\n    id: 'insights-to-concept',\n    slug: 'insights-to-concept',\n    title: 'От инсайтов к концепции',\n    pathTitle: 'Design Process',\n    skill: 'process',\n    difficulty: 'easy',\n    estimatedMinutes: 11,\n    objectives: [\n        'Превращать сырые данные в инсайты, а не в пересказ',\n        'Идти от концепции и мудборда к вайрфреймам',\n        'Проверять структуру на скелете до визуала'\n    ],\n    prerequisites: [\n        'brief-research',\n        'research-methods'\n    ],\n    theory: [\n        'Данные собраны — но сами по себе они ещё не решение. Финальный урок серии: как превратить исследование в направление и первый скелет экрана.',\n        '**Синтез: данные → инсайты.** Инсайт — это вывод и паттерн («люди бросают оплату, потому что не доверяют незнакомому шагу»), а не сырая заметка или число. Груда наблюдений без синтеза не двигает проект.',\n        '**Концепция и мудборд** задают направление до вёрстки: ключевая идея решения, тон, референсы. Это мост между «что мы поняли» и «что будем делать».',\n        '**Вайрфреймы** — скелет без цвета и типографики: блоки, иерархия, потоки. Здесь дёшево проверить структуру; ошибку логики лучше поймать на скелете, чем после дней отрисовки.',\n        'Полный порядок: бриф → исследование → **инсайты** → концепция → вайрфрейм → визуал. Каждый шаг опирается на предыдущий; прыжок сразу в «красивый макет» почти всегда возвращает с переделками.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Сразу финальный визуал без структуры',\n            visual: 'spacing-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Вайрфрейм-скелет до отрисовки визуала',\n            visual: 'spacing-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'itc-choose-1',\n            type: 'choose',\n            prompt: 'Что из этого — инсайт, а не просто данные?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Люди бросают оплату, потому что не доверяют незнакомому шагу «3-D Secure»'\n                },\n                {\n                    id: 'b',\n                    label: '68% сессий заканчиваются на шаге оплаты',\n                    hint: 'Это сырой факт — говорит «сколько», но не «почему». Инсайт объясняет причину.'\n                },\n                {\n                    id: 'c',\n                    label: 'Мы провели 8 интервью и опрос',\n                    hint: 'Это описание процесса, а не вывод из него.'\n                },\n                {\n                    id: 'd',\n                    label: 'Пользователи заходят в основном с мобильных',\n                    hint: 'Факт без интерпретации — что он меняет в решении?'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Инсайт объясняет причину и подсказывает действие: недоверие к незнакомому шагу → сделать его понятным и знакомым. Проценты и описание процесса — сырьё; инсайт рождается из их синтеза.'\n        },\n        {\n            id: 'itc-order-1',\n            type: 'order',\n            prompt: 'Расставь этапы от старта проекта к первому макету.',\n            items: [\n                {\n                    id: 'brief',\n                    label: 'Бриф / цели',\n                    size: 'body'\n                },\n                {\n                    id: 'research',\n                    label: 'Исследование',\n                    size: 'body'\n                },\n                {\n                    id: 'insight',\n                    label: 'Инсайты',\n                    size: 'body'\n                },\n                {\n                    id: 'concept',\n                    label: 'Концепция и мудборд',\n                    size: 'body'\n                },\n                {\n                    id: 'wire',\n                    label: 'Вайрфреймы',\n                    size: 'body'\n                }\n            ],\n            correctOrder: [\n                'brief',\n                'research',\n                'insight',\n                'concept',\n                'wire'\n            ],\n            explanation: 'Сначала фиксируем задачу (бриф), собираем данные (исследование), превращаем их в выводы (инсайты), задаём направление (концепция) и только потом строим скелет (вайрфреймы). Визуал — уже поверх готового каркаса.'\n        },\n        {\n            id: 'itc-choose-2',\n            type: 'choose',\n            prompt: 'Почему вайрфреймы делают до визуала?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Дёшево проверить структуру и логику, пока не вложен визуал'\n                },\n                {\n                    id: 'b',\n                    label: 'Чтобы клиент увидел финальный дизайн раньше',\n                    hint: 'Вайрфрейм — это скелет, а не финал.'\n                },\n                {\n                    id: 'c',\n                    label: 'Потому что так требует Figma',\n                    hint: 'Инструмент не диктует этап процесса.'\n                },\n                {\n                    id: 'd',\n                    label: 'Чтобы сэкономить на исследовании',\n                    hint: 'Вайрфреймы не заменяют ресёрч, они идут после него.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Вайрфрейм — скелет без цвета и типографики. На нём дёшево и быстро проверяются иерархия, блоки и потоки. Ошибку структуры лучше поймать здесь, а не после дней отрисовки визуала.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'itc-figma-1',\n        type: 'figma-link',\n        prompt: 'Собери вайрфрейм одного экрана (например, экран оформления заказа) в Figma: только блоки, иерархия и потоки, без цвета и финальной типографики. Пришли ссылку.',\n        checklist: [\n            'Есть чёткая иерархия блоков (что главное, что второстепенное)',\n            'Показан основной поток/действие экрана',\n            'Виден инсайт в решении (например, шаг оплаты сделан понятным)',\n            'Нет финального визуала — это скелет, а не отрисовка'\n        ],\n        explanation: 'Вайрфрейм проверяет структуру до визуала. Если на скелете уже видно, что делает экран, куда ведёт главный путь и как учтён ключевой инсайт, — основа заложена верно, и визуал ляжет на готовый каркас.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/insights-to-concept.ts\n");

