eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   microTypography: () => (/* binding */ microTypography)\n/* harmony export */ });\n/**\n * UI Foundations — micro-typography: the small rules that separate amateur from\n * professional text. Line-height vs size, trim zone, dashes/quotes/orphans.\n */ const microTypography = {\n    id: 'micro-typography',\n    slug: 'micro-typography',\n    title: 'Микротипографика',\n    pathTitle: 'UI Foundations',\n    skill: 'typography',\n    difficulty: 'medium',\n    estimatedMinutes: 12,\n    objectives: [\n        'Связывать межстрочный интервал с кеглем текста',\n        'Правильно применять дефис, тире и кавычки-ёлочки',\n        'Убирать висячие предлоги и понимать trim zone вокруг текста'\n    ],\n    prerequisites: [\n        'type-hierarchy'\n    ],\n    theory: [\n        'Правило межстрочного: **чем крупнее кегль, тем меньше относительный интерлиньяж**. Мелкий текст (12–16px) дышит при line-height ~1.4–1.5; крупный заголовок (32px+) достаточно 1.1–1.2, иначе строки «расползаются».',\n        'Практический ориентир из шпаргалки: `font-size 12px + 2–4px = 14–16px line-height`. Прибавка в абсолютных пикселях примерно постоянна, поэтому в процентах она у крупного текста меньше.',\n        '**Дефис (-)** соединяет части слова (из-за, кто-то). **Тире (—)** разделяет части предложения и ставится с пробелами. Это разные знаки, не взаимозаменяемые.',\n        'В русском тексте кавычки — **«ёлочки»**, а не английские \"лапки\". Не забываем про букву **ё** и **висячие предлоги**: короткий предлог не должен оставаться в конце строки — его переносят к следующему слову неразрывным пробелом.',\n        '**Trim zone** — пустое поле шрифта над и под буквами. У обычного текстового блока есть extra font space; функция `text-box-trim` срезает её, чтобы отбивки считались от самих букв, а не от невидимой рамки строки.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Крупный заголовок с line-height 1.6 — строки разъезжаются',\n            visual: 'hierarchy-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Тот же заголовок с line-height 1.15 — плотно и собранно',\n            visual: 'hierarchy-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'mt-choose-1',\n            type: 'choose',\n            picker: 'segmented',\n            prompt: 'Заголовок 32px. Какой относительный line-height уместнее?',\n            options: [\n                {\n                    id: 'a',\n                    label: '1.1'\n                },\n                {\n                    id: 'b',\n                    label: '1.5',\n                    hint: '1.5 — для мелкого текста; у крупного заголовка строки разъедутся.'\n                },\n                {\n                    id: 'c',\n                    label: '1.8',\n                    hint: 'Слишком много даже для абзаца, тем более для заголовка.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Чем крупнее кегль, тем меньше нужен относительный интерлиньяж. Для 32px хватает ~1.1–1.2: буквы и так крупные, лишний воздух между строк только рвёт заголовок.'\n        },\n        {\n            id: 'mt-choose-2',\n            type: 'choose',\n            prompt: 'Основной текст 14px. Какой line-height даст комфортное чтение по правилу «+2–4px»?',\n            options: [\n                {\n                    id: 'a',\n                    label: '14px (1.0)',\n                    hint: 'Строки слипнутся — нет воздуха между ними.'\n                },\n                {\n                    id: 'b',\n                    label: '17px (~1.2)'\n                },\n                {\n                    id: 'c',\n                    label: '28px (2.0)',\n                    hint: 'Вдвое — абзац рассыпается на отдельные строки.'\n                },\n                {\n                    id: 'd',\n                    label: '12px (0.85)',\n                    hint: 'Меньше кегля — строки налезают друг на друга.'\n                }\n            ],\n            correctOptionId: 'b',\n            explanation: '14px + ~3px = 17px (около 1.2). Для тела абзаца часто берут и повыше (1.4–1.5), но прибавка «+2–4px» — надёжная отправная точка, привязанная к кеглю, а не к случайному проценту.'\n        },\n        {\n            id: 'mt-choose-3',\n            type: 'choose',\n            prompt: 'Где НУЖНО тире (—), а не дефис (-)?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'из-за погоды',\n                    hint: 'Здесь дефис: он соединяет части слова.'\n                },\n                {\n                    id: 'b',\n                    label: 'кто-то пришёл',\n                    hint: 'Здесь дефис — часть местоимения.'\n                },\n                {\n                    id: 'c',\n                    label: 'Дизайн — это решение задач'\n                },\n                {\n                    id: 'd',\n                    label: 'бело-синий флаг',\n                    hint: 'Составное прилагательное пишется через дефис.'\n                }\n            ],\n            correctOptionId: 'c',\n            explanation: 'Тире (—) разделяет части предложения и ставится с пробелами по бокам. Дефис (-) — орфографический знак внутри слова: «из-за», «кто-то», «бело-синий».'\n        },\n        {\n            id: 'mt-match-1',\n            type: 'match',\n            prompt: 'Соедини типографский знак с его правильным применением.',\n            pairs: [\n                {\n                    id: 'hyphen',\n                    left: '- (дефис)',\n                    right: 'из-за, кто-то'\n                },\n                {\n                    id: 'dash',\n                    left: '— (тире)',\n                    right: 'Дизайн — это система'\n                },\n                {\n                    id: 'quotes',\n                    left: '«ёлочки»',\n                    right: 'русские кавычки'\n                },\n                {\n                    id: 'yo',\n                    left: 'ё',\n                    right: 'всё, ещё, приём'\n                }\n            ],\n            explanation: 'Каждый знак несёт свою роль: дефис — внутри слова, тире — между частями фразы, «ёлочки» — стандартные русские кавычки, а ё — не роскошь, а часть корректного текста.'\n        },\n        {\n            id: 'mt-choose-4',\n            type: 'choose',\n            prompt: 'Строка заканчивается коротким предлогом: «…мы говорили о » и перенос. Как правильно?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Оставить предлог в конце строки',\n                    hint: 'Это и есть висячий предлог — его избегают.'\n                },\n                {\n                    id: 'b',\n                    label: 'Перенести предлог к следующему слову неразрывным пробелом'\n                },\n                {\n                    id: 'c',\n                    label: 'Разбить слово после предлога дефисом',\n                    hint: 'Перенос слова здесь ни при чём.'\n                },\n                {\n                    id: 'd',\n                    label: 'Ничего, это не важно',\n                    hint: 'Висячий предлог выдаёт небрежную вёрстку.'\n                }\n            ],\n            correctOptionId: 'b',\n            explanation: 'Короткие слова (предлоги, союзы, «я») не оставляют в конце строки. Их «приклеивают» к следующему слову неразрывным пробелом (nbsp), чтобы они переносились вместе.'\n        },\n        {\n            id: 'mt-trim-1',\n            type: 'trim-zone',\n            prompt: 'У кнопки «Submit» сверху и снизу лишнее поле шрифта (trim zone). Подрежь его, пока текст не встанет оптически по центру — но не заезжай на сами буквы.',\n            label: 'Submit',\n            targetTrim: 9,\n            maxTrim: 18,\n            tolerance: 1,\n            explanation: 'Розовые полосы — невидимая trim zone (extra font space) над и под буквами. Срезав её (как делает `text-box-trim`), ты приравниваешь отбивки к самим глифам, и padding начинает считаться от букв. Перебор срезает уже буквы — сладкая точка ровно там, где полосы исчезли.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'mt-choose-5',\n        type: 'choose',\n        prompt: 'Кнопка «Submit» имеет заметный вертикальный люфт сверху и снизу текста, хотя padding задан симметрично. В чём причина и решение?',\n        options: [\n            {\n                id: 'a',\n                label: 'Это extra font space (trim zone); срезать через text-box-trim'\n            },\n            {\n                id: 'b',\n                label: 'Padding задан неверно — увеличить его',\n                hint: 'Padding как раз симметричен; лишний зазор даёт сам шрифт.'\n            },\n            {\n                id: 'c',\n                label: 'Проблема в line-height кнопки',\n                hint: 'Дело не в интерлиньяже одной строки, а в невидимом поле шрифта.'\n            },\n            {\n                id: 'd',\n                label: 'Нужно поменять шрифт',\n                hint: 'Trim zone есть у любого шрифта — её срезают, а не меняют гарнитуру.'\n            }\n        ],\n        correctOptionId: 'a',\n        explanation: 'Вокруг глифов есть невидимая trim zone (extra font space). Отбивки от рамки строки визуально «не равны» отбивкам от самих букв. `text-box-trim` срезает это поле, и padding начинает считаться от букв — кнопка выглядит оптически выверенной.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/micro-typography.ts\n");

