eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   researchMethods: () => (/* binding */ researchMethods)\n/* harmony export */ });\n/**\n * Design Process — series part 2 of 3.\n * Research methods: interviews, surveys, competitor analysis, analytics — and\n * matching the method to the question (qualitative \"why\" vs quantitative \"how many\").\n */ const researchMethods = {\n    id: 'research-methods',\n    slug: 'research-methods',\n    title: 'Методы исследования',\n    pathTitle: 'Design Process',\n    skill: 'process',\n    difficulty: 'easy',\n    estimatedMinutes: 11,\n    objectives: [\n        'Выбирать метод под вопрос: «почему» или «сколько»',\n        'Превращать анализ конкурентов в выводы, а не в скриншоты',\n        'Отличать качественные и количественные данные'\n    ],\n    prerequisites: [\n        'brief-research'\n    ],\n    theory: [\n        'Бриф задал вопрос — исследование даёт на него ответ **на данных**, а не на вкусе. Второй урок серии — про то, каким методом добыть нужный ответ.',\n        '**Качественные vs количественные.** Качественные (интервью, наблюдение) отвечают на **«почему»** и вскрывают причины; количественные (опросы, аналитика) — на **«сколько / как часто»** и дают масштаб. Метод выбирают под вопрос, а не наоборот.',\n        '**Анализ конкурентов** — источник паттернов (что уже стало стандартом и не стоит изобретать) и пробелов (что решают плохо — туда можно зайти). Итог — выводы, а не папка скриншотов.',\n        '**Аналитика** показывает, что люди делают **на самом деле**, а не что говорят. Слова и поведение расходятся — поэтому сильное исследование обычно сочетает несколько методов.'\n    ],\n    examples: [],\n    exercises: [\n        {\n            id: 'rm-choose-1',\n            type: 'choose',\n            prompt: 'Зачем анализировать конкурентов перед проектированием?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Найти рабочие паттерны и незанятые пробелы'\n                },\n                {\n                    id: 'b',\n                    label: 'Чтобы скопировать лучший экран',\n                    hint: 'Копия чужого решения не учитывает вашу задачу и пользователя.'\n                },\n                {\n                    id: 'c',\n                    label: 'Чтобы убедиться, что рынок пуст',\n                    hint: 'Даже занятый рынок оставляет пробелы — их и ищем.'\n                },\n                {\n                    id: 'd',\n                    label: 'Это формальность для отчёта',\n                    hint: 'Анализ должен давать выводы, а не строчку в презентации.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Анализ конкурентов — источник паттернов (что уже стало стандартом и не стоит изобретать) и пробелов (что решают плохо — туда можно зайти). Итог анализа — выводы, а не скриншоты ради галочки.'\n        },\n        {\n            id: 'rm-choose-2',\n            type: 'choose',\n            prompt: 'Нужно понять, ПОЧЕМУ люди бросают корзину на шаге оплаты. Какой метод даст ответ?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Глубинные интервью с бросившими корзину'\n                },\n                {\n                    id: 'b',\n                    label: 'Опрос «оцените удобство от 1 до 5»',\n                    hint: 'Даст число, но не причину — «почему» так не вскрыть.'\n                },\n                {\n                    id: 'c',\n                    label: 'Только цифры воронки в аналитике',\n                    hint: 'Покажет ГДЕ отваливаются, но не ПОЧЕМУ.'\n                },\n                {\n                    id: 'd',\n                    label: 'Спросить мнение команды на планёрке',\n                    hint: 'Это догадки команды, а не данные о пользователях.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Вопрос «почему» — качественный. Интервью вскрывает причины: скрытые комиссии, недоверие к оплате, непонятный шаг. Аналитика покажет, где отваливаются, но причину даст разговор.'\n        },\n        {\n            id: 'rm-match',\n            type: 'match',\n            prompt: 'Соедини метод с вопросом, на который он отвечает.',\n            pairs: [\n                {\n                    id: 'p1',\n                    left: 'Глубинное интервью',\n                    right: 'Почему так происходит'\n                },\n                {\n                    id: 'p2',\n                    left: 'Опрос',\n                    right: 'Как часто и у скольких'\n                },\n                {\n                    id: 'p3',\n                    left: 'Аналитика продукта',\n                    right: 'Что делают на самом деле'\n                }\n            ],\n            explanation: 'Каждый метод силён своим вопросом: интервью — про причины, опрос — про масштаб, аналитика — про реальное поведение. Сильное исследование сочетает их, а не полагается на один.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'rm-choose-mastery',\n        type: 'choose',\n        prompt: 'Гипотеза: «новую функцию не замечают». Нужно быстро понять масштаб — у скольких пользователей это так. С чего начать?',\n        options: [\n            {\n                id: 'a',\n                label: 'Посмотреть аналитику: сколько людей вообще открывали функцию'\n            },\n            {\n                id: 'b',\n                label: 'Провести 5 глубинных интервью',\n                hint: 'Интервью раскроют «почему», но не дадут масштаб «у скольких».'\n            },\n            {\n                id: 'c',\n                label: 'Спросить у стейкхолдеров их мнение',\n                hint: 'Мнение — не данные о поведении пользователей.'\n            },\n            {\n                id: 'd',\n                label: 'Сразу переделать функцию',\n                hint: 'Решать до замера масштаба — риск лечить несуществующую проблему.'\n            }\n        ],\n        correctOptionId: 'a',\n        explanation: 'Вопрос «у скольких» — количественный, и аналитика ответит быстрее всего: видно охват и частоту. А уже потом интервью объяснят «почему не замечают». Сначала масштаб — затем причины.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/research-methods.ts\n");

