eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   responsiveLayout: () => (/* binding */ responsiveLayout)\n/* harmony export */ });\n/**\n * UI Foundations — responsive/adaptive layout: mobile vs desktop type scales,\n * breakpoints, and reflowing composition instead of shrinking it.\n */ const responsiveLayout = {\n    id: 'responsive-layout',\n    slug: 'responsive-layout',\n    title: 'Адаптив: mobile и desktop',\n    pathTitle: 'UI Foundations',\n    skill: 'responsive',\n    difficulty: 'medium',\n    estimatedMinutes: 14,\n    objectives: [\n        'Задавать разные типографические шкалы для mobile и desktop',\n        'Понимать брейкпоинты и перекомпоновку, а не простое масштабирование',\n        'Сохранять иерархию и тап-цели на узких экранах'\n    ],\n    prerequisites: [\n        'type-hierarchy',\n        'grids-composition'\n    ],\n    theory: [\n        'Адаптив — это **перекомпоновка**, а не уменьшение копии десктопа. Блоки перестраиваются: многоколоночная раскладка складывается в одну колонку, навигация — в бургер, боковая панель уходит вниз.',\n        'Типографика тоже адаптируется. Пример шкал из практики: на **mobile** H1 32 / H2 28 / H3 24 / H4 20; на **desktop** H1 40 / H2 32 / H3 28 / H4 24. Заголовки на большом экране крупнее, тело остаётся читаемым (14–16px).',\n        '**Брейкпоинт** — ширина, на которой раскладка меняется. Их задают по контенту (где вёрстка «ломается»), а не по конкретным моделям устройств.',\n        'На узких экранах критичны **тап-цели** (≥44px) и приоритет: главное действие остаётся на виду, второстепенное прячется в меню. Иерархия важнее, чем «влезло всё».',\n        'Правило: сначала проектируй под самый узкий экран (mobile-first) — это заставляет отобрать главное. Расширять проще, чем впихивать.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Десктоп ужат до мобильного — всё мелкое и тесное',\n            visual: 'spacing-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Раскладка перестроена в одну колонку — читаемо',\n            visual: 'spacing-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'rl-choose-1',\n            type: 'choose',\n            prompt: 'Что значит «адаптивная раскладка» в правильном смысле?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Блоки перекомпоновываются под ширину экрана'\n                },\n                {\n                    id: 'b',\n                    label: 'Десктопный макет пропорционально уменьшается',\n                    hint: 'Тогда текст и тап-цели станут нечитаемо мелкими.'\n                },\n                {\n                    id: 'c',\n                    label: 'Для каждого устройства рисуют отдельный сайт',\n                    hint: 'Это дубли; адаптив — одна система, меняющая раскладку.'\n                },\n                {\n                    id: 'd',\n                    label: 'Просто включается горизонтальный скролл',\n                    hint: 'Горизонтальный скролл на мобильном — антипаттерн.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Адаптив перестраивает композицию: колонки складываются, навигация сворачивается, порядок блоков меняется. Это не масштабирование картинки и не отдельные сайты, а одна гибкая система.'\n        },\n        {\n            id: 'rl-choose-2',\n            type: 'choose',\n            picker: 'segmented',\n            prompt: 'H1 на desktop по практической шкале — какой кегль?',\n            options: [\n                {\n                    id: 'a',\n                    label: '24',\n                    hint: 'Это ближе к H4 desktop / H3.'\n                },\n                {\n                    id: 'b',\n                    label: '32',\n                    hint: 'Это H1 mobile / H2 desktop.'\n                },\n                {\n                    id: 'c',\n                    label: '40'\n                }\n            ],\n            correctOptionId: 'c',\n            explanation: 'На широком экране заголовок может звучать громче: H1 desktop ≈ 40px против 32px на mobile. Тело при этом остаётся ~14–16px — крупный заголовок ведёт, текст не раздувается.'\n        },\n        {\n            id: 'rl-scale-1',\n            type: 'scale-ramp',\n            prompt: 'Собери мобильную шкалу: базовый размер тела 16px, соотношение 1.25. Проверь, как аккуратно вырастают заголовки для узкого экрана.',\n            targetBase: 16,\n            targetRatio: 1.25,\n            explanation: 'Та же логика модульной шкалы работает и в адаптиве: одно соотношение (1.25) от базы 16px даёт согласованный ряд. На desktop базу и/или шаг можно увеличить, но принцип «один коэффициент» сохраняется.'\n        },\n        {\n            id: 'rl-choose-3',\n            type: 'choose',\n            prompt: 'Как выбирать брейкпоинты?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'По контенту — там, где вёрстка начинает ломаться'\n                },\n                {\n                    id: 'b',\n                    label: 'Точно под iPhone/iPad и популярные модели',\n                    hint: 'Моделей слишком много и они меняются; привязка к ним хрупкая.'\n                },\n                {\n                    id: 'c',\n                    label: 'Ровно через каждые 100px',\n                    hint: 'Механический шаг не связан с реальной вёрсткой.'\n                },\n                {\n                    id: 'd',\n                    label: 'Один брейкпоинт на всё',\n                    hint: 'Обычно нужно несколько точек перекомпоновки.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Брейкпоинты ставят там, где контент перестаёт нормально помещаться. Привязка к конкретным устройствам устаревает; привязка к поведению вёрстки — устойчива.'\n        },\n        {\n            id: 'rl-resize-1',\n            type: 'resize-frame',\n            prompt: 'Потяни рамку и найди планшетную ширину — 768px. Заметь, как на этой точке галерея перестраивается с одной колонки на две.',\n            minWidth: 320,\n            maxWidth: 1200,\n            targetWidth: 768,\n            tolerance: 24,\n            breakpoints: [\n                {\n                    at: 0,\n                    columns: 1,\n                    label: 'Мобайл'\n                },\n                {\n                    at: 600,\n                    columns: 2,\n                    label: 'Планшет'\n                },\n                {\n                    at: 960,\n                    columns: 3,\n                    label: 'Десктоп'\n                }\n            ],\n            explanation: 'Брейкпоинт — это ширина, на которой раскладка перестраивается. Около 768px одна колонка становится тесной для карточек, и сетка разворачивается в две. Точку ставят там, где контент «просит» перекомпоновки, а не под конкретную модель планшета.'\n        },\n        {\n            id: 'rl-tap-target',\n            type: 'tap-target',\n            prompt: 'Кнопка слишком мелкая для пальца. Увеличь её до безопасной тап-цели ≥44px.',\n            hint: 'HIG и WCAG 2.5.5 сходятся на минимуме 44px по каждой стороне — ниже палец начинает промахиваться.',\n            explanation: 'На тач-экране в кнопку целятся пальцем, а не курсором, поэтому у неё должна быть площадь, а не только надпись. Минимум 44×44px (HIG, WCAG 2.5.5) — ниже растёт число промахов, особенно на ходу и одной рукой. Маленькая, но попадаемая цель важнее плотной раскладки.'\n        },\n        {\n            id: 'rl-choose-4',\n            type: 'choose',\n            prompt: 'Почему проектируют mobile-first?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Узкий экран заставляет отобрать главное; расширять проще'\n                },\n                {\n                    id: 'b',\n                    label: 'Потому что мобильных пользователей всегда больше',\n                    hint: 'Не всегда — и дело не в статистике, а в дисциплине приоритетов.'\n                },\n                {\n                    id: 'c',\n                    label: 'Так требует CSS',\n                    hint: 'CSS позволяет и то, и другое; это методология, а не ограничение.'\n                },\n                {\n                    id: 'd',\n                    label: 'Чтобы не делать десктоп вообще',\n                    hint: 'Десктоп делают — просто расширяют от мобильной базы.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'На маленьком экране всё не помещается, и это полезно: ты вынужден решить, что действительно главное. Добавлять пространство на десктопе легче, чем ужимать перегруженный макет.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'rl-choose-5',\n        type: 'choose',\n        prompt: 'Десктопная шапка: логотип, 6 пунктов меню, поиск, профиль. Как адаптировать её под мобильный?',\n        options: [\n            {\n                id: 'a',\n                label: 'Логотип + ключевое действие видимы, меню — в бургер'\n            },\n            {\n                id: 'b',\n                label: 'Уменьшить всё, чтобы влезло в одну строку',\n                hint: 'Пункты станут мелкими и непопадаемыми — тап-цели меньше 44px.'\n            },\n            {\n                id: 'c',\n                label: 'Оставить как есть с горизонтальным скроллом',\n                hint: 'Горизонтальный скролл шапки — неочевидно и неудобно.'\n            },\n            {\n                id: 'd',\n                label: 'Убрать навигацию совсем',\n                hint: 'Навигация нужна — её сворачивают, а не удаляют.'\n            }\n        ],\n        correctOptionId: 'a',\n        explanation: 'На мобильном держат видимым главное (логотип, ключевое действие), а полное меню сворачивают в бургер. Это сохраняет иерархию и крупные тап-цели вместо того, чтобы впихнуть весь десктоп в узкую полосу.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/responsive-layout.ts\n");

