eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   lessons: () => (/* binding */ lessons),\n/* harmony export */   spacing8pt: () => (/* binding */ spacing8pt)\n/* harmony export */ });\n/**\n * First lesson — the MVP vertical.\n * Theme: Spacing & the 8pt Grid. Demonstrates the full core loop.\n */ const spacing8pt = {\n    id: 'spacing-8pt',\n    slug: 'spacing-8pt-grid',\n    title: 'Spacing и 8pt-сетка',\n    pathTitle: 'UI Foundations',\n    skill: 'spacing',\n    difficulty: 'intro',\n    estimatedMinutes: 8,\n    objectives: [\n        'Понять, зачем интерфейсам единая сетка отступов',\n        'Научиться выбирать значения, кратные 8 (с полушагом 4)',\n        'Отличать консистентный ритм от случайных «magic numbers»'\n    ],\n    prerequisites: [],\n    theory: [\n        'Профессиональные интерфейсы строятся на **8pt-сетке**: все отступы, паддинги и разрывы кратны 8px (4px — допустимый полушаг для тонкой настройки).',\n        'Сетка убирает произвол. Вместо «на глаз 13px или 15px» — предсказуемый ритм: 8, 16, 24, 32. Глаз читает такой интерфейс как аккуратный.',\n        'Случайные значения (7px, 13px, 19px) называют **magic numbers** — они ломают консистентность и выдают любителя.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Случайные отступы 7 / 13 / 19px — ритма нет',\n            visual: 'spacing-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Отступы 8 / 16 / 24px — чистый ритм 8pt',\n            visual: 'spacing-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'sp-choose-1',\n            type: 'choose',\n            picker: 'segmented',\n            prompt: 'Какое значение отступа соответствует 8pt-сетке?',\n            options: [\n                {\n                    id: 'a',\n                    label: '13px',\n                    hint: '13 не кратно 8 и не 4 — это magic number.'\n                },\n                {\n                    id: 'b',\n                    label: '16px'\n                },\n                {\n                    id: 'c',\n                    label: '18px',\n                    hint: '18 не кратно 8. Ближайшие валидные: 16 или 24.'\n                },\n                {\n                    id: 'd',\n                    label: '21px',\n                    hint: '21 не кратно 8 или 4.'\n                }\n            ],\n            correctOptionId: 'b',\n            explanation: '16px = 8 × 2 — идеально ложится на 8pt-сетку. Остальные значения не кратны 8 (и не 4), поэтому ломают ритм.'\n        },\n        {\n            id: 'sp-choose-2',\n            type: 'choose',\n            prompt: 'Между заголовком и текстом нужен разрыв чуть меньше 16px. Какое значение выбрать?',\n            options: [\n                {\n                    id: 'a',\n                    label: '10px',\n                    hint: '10 не на сетке. Полушаг даёт 12px.'\n                },\n                {\n                    id: 'b',\n                    label: '11px',\n                    hint: '11 — magic number.'\n                },\n                {\n                    id: 'c',\n                    label: '12px'\n                },\n                {\n                    id: 'd',\n                    label: '14px',\n                    hint: '14 не кратно 4. Ближайшие: 12 или 16.'\n                }\n            ],\n            correctOptionId: 'c',\n            explanation: '12px = 4 × 3 — это разрешённый полушаг сетки (кратен 4). Когда 16px велико, а 8px мало, 12px — правильный компромисс.'\n        },\n        {\n            id: 'sp-build-1',\n            type: 'build',\n            prompt: 'Собери auto-layout карточку на холсте: отступ между блоками 16px, внутренние поля 24px. Держись 8pt-сетки.',\n            blocks: 4,\n            step: 4,\n            min: 0,\n            max: 40,\n            target: {\n                gap: 16,\n                padding: 24\n            },\n            explanation: 'Отступ 16px (8×2) задаёт ровный вертикальный ритм между блоками, а поля 24px (8×3) дают карточке «дышащие» границы. Оба значения — на 8pt-сетке, поэтому композиция выглядит аккуратно.'\n        },\n        {\n            id: 'sp-align-1',\n            type: 'align',\n            prompt: 'Перетащи карточку так, чтобы она встала по центру фрейма. Она магнитится к направляющим и шагу 8pt.',\n            target: {\n                x: 'center',\n                y: 'middle'\n            },\n            explanation: 'Выравнивание по осям и привязка к сетке — основа опрятной композиции. Направляющие (левая/центр/правая, верх/центр/низ) — те же, что даёт Auto Layout: элементы встают предсказуемо, а не «примерно там».'\n        }\n    ],\n    masteryChallenge: {\n        id: 'sp-tune-1',\n        type: 'tune',\n        prompt: 'Подбери вертикальный отступ секции так, чтобы он лежал на 8pt-сетке и равнялся 24px.',\n        unitLabel: 'px',\n        min: 0,\n        max: 48,\n        step: 4,\n        correctValue: 24,\n        tolerance: 0,\n        explanation: '24px = 8 × 3 — крупный, «дышащий» отступ для разделения секций. Он кратен 8 и держит вертикальный ритм страницы.'\n    }\n};\nconst lessons = {\n    [spacing8pt.slug]: spacing8pt\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/spacing-8pt.ts\n");

