eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   userFlowsEdge: () => (/* binding */ userFlowsEdge)\n/* harmony export */ });\n/**\n * UX Foundations — user flows series, part 2 of 3.\n * Branches and edge cases: errors, empty/loading/offline states as part of the\n * flow, and always giving a path back.\n */ const userFlowsEdge = {\n    id: 'user-flows-edge',\n    slug: 'user-flows-edge',\n    title: 'Потоки: ветки и крайние случаи',\n    pathTitle: 'UX Foundations',\n    skill: 'flows',\n    difficulty: 'medium',\n    estimatedMinutes: 11,\n    objectives: [\n        'Закладывать ошибки и пустые состояния в поток заранее',\n        'Подбирать правильное состояние под каждую ситуацию',\n        'Давать выход из каждой ветки ошибки, а не тупик'\n    ],\n    prerequisites: [\n        'user-flows'\n    ],\n    theory: [\n        'Happy path — только половина потока. Реальный сценарий **ветвится**: что-то не найдено, оплата отклонена, сеть пропала. Второй урок — про эти ветки.',\n        '**Крайние случаи (edge cases)** закладывают заранее, а не «когда дойдут руки». Пустая корзина, отклонённая оплата, нет сети, нет результатов поиска — всё это состояния, которые человек точно увидит.',\n        'Каждой ситуации — своё **состояние**: ожидание → индикатор загрузки, пусто → пустое состояние с подсказкой, сбой → ошибка с причиной. Пустой белый экран — это не «нет данных», это «дизайнер забыл».',\n        'Ветка ошибки всегда **ведёт куда-то**: причина + действие для восстановления. Тупик, из которого некуда идти, — худший исход потока.'\n    ],\n    examples: [\n        {\n            kind: 'bad',\n            caption: 'Пустой экран без объяснения и действия',\n            visual: 'empty-bad'\n        },\n        {\n            kind: 'good',\n            caption: 'Пустое состояние: что случилось и что делать',\n            visual: 'empty-good'\n        }\n    ],\n    exercises: [\n        {\n            id: 'ufe-choose-1',\n            type: 'choose',\n            prompt: 'Что такое edge case в потоке?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Ситуация вне happy path: ошибка, пустота, сбой'\n                },\n                {\n                    id: 'b',\n                    label: 'Красиво оформленный экран успеха',\n                    hint: 'Успех — это happy path, а не крайний случай.'\n                },\n                {\n                    id: 'c',\n                    label: 'Кнопка на краю экрана',\n                    hint: 'Речь про сценарий, а не про расположение элемента.'\n                },\n                {\n                    id: 'd',\n                    label: 'Самый частый путь пользователя',\n                    hint: 'Частый путь — это как раз happy path.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Edge case — всё, что отклоняется от идеального сценария: сбой сети, пустой список, отклонённая оплата. Эти ветки закладывают заранее, потому что пользователь их обязательно встретит.'\n        },\n        {\n            id: 'ufe-match',\n            type: 'match',\n            prompt: 'Соедини ситуацию с состоянием, которое нужно показать.',\n            pairs: [\n                {\n                    id: 'p1',\n                    left: 'Список ещё грузится',\n                    right: 'Скелетоны / индикатор'\n                },\n                {\n                    id: 'p2',\n                    left: 'В поиске ничего не найдено',\n                    right: 'Пустое состояние с подсказкой'\n                },\n                {\n                    id: 'p3',\n                    left: 'Пропала сеть',\n                    right: 'Баннер + кнопка «Повторить»'\n                }\n            ],\n            explanation: 'Каждой ветке — своё состояние: ожидание показывает индикатор, пустота объясняет и подсказывает шаг, сбой называет причину и даёт повторить. Так поток не обрывается в тупик.'\n        },\n        {\n            id: 'ufe-choose-2',\n            type: 'choose',\n            prompt: 'Пользователь искал товар, совпадений нет. Что показать?',\n            options: [\n                {\n                    id: 'a',\n                    label: 'Пустое состояние: «Ничего не найдено» + советы и сброс фильтров'\n                },\n                {\n                    id: 'b',\n                    label: 'Пустой белый экран',\n                    hint: 'Похоже на баг: непонятно, сломалось или правда пусто.'\n                },\n                {\n                    id: 'c',\n                    label: 'Прошлые результаты, будто ничего не менялось',\n                    hint: 'Вводит в заблуждение — человек решит, что поиск не сработал.'\n                },\n                {\n                    id: 'd',\n                    label: 'Ошибку «Что-то пошло не так»',\n                    hint: 'Это не ошибка системы — просто нет совпадений.'\n                }\n            ],\n            correctOptionId: 'a',\n            explanation: 'Отсутствие результатов — нормальная ветка, а не сбой. Хорошее пустое состояние объясняет, что совпадений нет, и подсказывает выход: смягчить запрос, сбросить фильтры, посмотреть похожее.'\n        }\n    ],\n    masteryChallenge: {\n        id: 'ufe-figma-1',\n        type: 'figma-link',\n        prompt: 'Начерти в Figma поток «Забыл пароль»: от клика на ссылке до успешного входа с новым паролем. Отметь happy path и минимум одну ветку ошибки (например, email не найден).',\n        checklist: [\n            'Виден happy path от точки входа до успеха',\n            'Есть хотя бы одна ветка ошибки, а не только удачный сценарий',\n            'Ветка ошибки ведёт к восстановлению, а не в тупик',\n            'Отмечено, куда ведёт каждая кнопка/ссылка'\n        ],\n        explanation: 'Поток «Забыл пароль» — короткий, но с обязательной веткой ошибки (email не найден, ссылка устарела). Хорошая схема показывает обе стороны: и happy path, и что происходит — и куда ведёт — когда что-то идёт не так.'\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/lessons/user-flows-edge.ts\n");

